import{_ as r,o,c as d,ag as s}from"./chunks/framework.D5hoimZQ.js";const b=JSON.parse('{"title":"Raspberry Pi 3 Model B+：识别、核实规格与用途判断","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/self-hosting/raspberry-pi-3b-plus.md","filePath":"topics/self-hosting/raspberry-pi-3b-plus.md"}'),e={name:"topics/self-hosting/raspberry-pi-3b-plus.md"};function a(n,t,i,g,l,h){return o(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="raspberry-pi-3-model-b-识别、核实规格与用途判断" tabindex="-1">Raspberry Pi 3 Model B+：识别、核实规格与用途判断 <a class="header-anchor" href="#raspberry-pi-3-model-b-识别、核实规格与用途判断" aria-label="Permalink to &quot;Raspberry Pi 3 Model B+：识别、核实规格与用途判断&quot;">​</a></h1><blockquote><p><strong>来源</strong>：2026-10-20 飞书分享（用户拍摄自有设备照片 5 张，无文字说明） <strong>核实</strong>：英文维基 <code>Raspberry Pi</code> + 中文维基 <code>树莓派</code> 原文，2026-10-20 关键词：树莓派、Raspberry Pi、Raspberry Pi 3 Model B+、3B+、BCM2837、ARM Cortex-A53、单板计算机、SBC、Homelab、自托管、Self-hosting、树莓派用途、本地 LLM 跑不动、AdGuard Home、Pi-hole、DNS 去广告、Tailscale、MQTT、传感器网关、看门狗、健康检查、Home Assistant、PoE、双频 Wi-Fi、micro-USB 供电、USB 启动、网络启动、数据主权、常驻节点</p></blockquote><hr><h2 id="一、设备识别-照片实录" tabindex="-1">一、设备识别（照片实录） <a class="header-anchor" href="#一、设备识别-照片实录" aria-label="Permalink to &quot;一、设备识别（照片实录）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>观察</th></tr></thead><tbody><tr><td>型号</td><td><strong>Raspberry Pi 3 Model B+</strong>（PCB 丝印 &quot;Raspberry Pi 3 Model B+&quot; + &quot;© Raspberry Pi 2017&quot;）</td></tr><tr><td>外壳</td><td>透明硬塑料盒；顶面圆形散热开孔，中心为<strong>铝制同心圆散热片</strong></td></tr><tr><td>状态</td><td><strong>红色 LED 常亮</strong>（已通电）；<strong>RJ45 已插灰色网线</strong>（已联网）</td></tr><tr><td>供电</td><td>白线接 <strong>micro-USB</strong> 电源口</td></tr><tr><td>USB</td><td>一根 &quot;GREEN <strong>USB 3.0 AM TO BM</strong>&quot; 线（打印机／硬盘盒类外设用线型）插在 USB-A 口</td></tr><tr><td>布局</td><td>一侧 RJ45 + USB-A ×2（照片可见），另一侧 AV 孔；板与壳用小螺丝固定</td></tr></tbody></table><hr><h2 id="二、核实规格-逐条标来源-不凭记忆" tabindex="-1">二、核实规格（逐条标来源，不凭记忆） <a class="header-anchor" href="#二、核实规格-逐条标来源-不凭记忆" aria-label="Permalink to &quot;二、核实规格（逐条标来源，不凭记忆）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>事实</th><th>来源</th></tr></thead><tbody><tr><td><strong>发布时间</strong></td><td><strong>2018 年 Pi Day（3 月 14 日）</strong></td><td>🇨🇳 中文维基原文</td></tr><tr><td>CPU</td><td><strong>1.4 GHz 64-bit</strong> Broadcom（BCM2837 系）</td><td>中文维基 &quot;更快的 1.4 GHz 64-bit 处理器&quot;；英文维基 <code>1.4 GHz</code> 命中</td></tr><tr><td>相对 3B 的升级</td><td><strong>更快的以太网 + 双频 Wi-Fi</strong></td><td>🇬🇧 英文维基：&quot;The Raspberry Pi 3B+ <strong>adds faster Ethernet and dual-band WiFi</strong>&quot;</td></tr><tr><td>Wi-Fi</td><td><strong>2.4 / 5 GHz 双频 802.11ac</strong></td><td>中文维基</td></tr><tr><td>以太网</td><td><strong>不是全速千兆</strong> —— 英文维基只把 &quot;<strong>full</strong> gigabit Ethernet&quot; 给 Pi 4 / Pi 5</td><td>🇬🇧 英文维基</td></tr><tr><td>PoE</td><td><strong>支持</strong>（板载取电需另配 PoE HAT）</td><td>中/英维基</td></tr><tr><td><strong>USB 启动 / 网络启动</strong></td><td><strong>支持，SD 卡不再是必须的</strong></td><td>中文维基 ← 实用信息</td></tr><tr><td>内存</td><td><strong>1 GB</strong>（由英文维基&quot;3A+ offers the <strong>same features as the 3B+</strong>, but with <strong>512 MB</strong> RAM&quot;反推）</td><td>🇬🇧 英文维基</td></tr><tr><td>供电接口</td><td><strong>micro-USB</strong>（对照：Pi 4 起改用 USB-C）</td><td>中文维基 Pi 4 段 + 照片</td></tr><tr><td>板印 &quot;© Raspberry Pi <strong>2017</strong>&quot;</td><td>⚠️ <strong>不是发布年份</strong> —— PCB 版权年 ≠ 型号发布年；3B+ 实为 <strong>2018-03</strong></td><td>中文维基</td></tr></tbody></table><hr><h2 id="三、⚠️-方法示范-连维基也要打折的一处" tabindex="-1">三、⚠️ 方法示范：连维基也要打折的一处 <a class="header-anchor" href="#三、⚠️-方法示范-连维基也要打折的一处" aria-label="Permalink to &quot;三、⚠️ 方法示范：连维基也要打折的一处&quot;">​</a></h2><p>中文维基原文：</p><blockquote><p>&quot;Raspberry Pi 3 Model B+ 于 2018 年的 Pi Day（3 月 14 日）发布，配备更快的 1.4 GHz 64-bit 处理器和<strong>快 3 倍的千兆以太网</strong>或 2.4 / 5 GHz 双频 802.11ac Wi-Fi（<strong>100 Mbit/s</strong>）。&quot;</p></blockquote><p><strong>这句话内部自相矛盾</strong>：</p><ul><li>3B 的网口是 <strong>100 Mbit/s</strong>；&quot;快 3 倍&quot; → 应为 <strong>≈300 Mbit/s</strong></li><li>括号却写成 100 Mbit/s（疑似笔误或与前代混淆）</li></ul><p><strong>裁决方法</strong>：用<strong>物理约束</strong>而不是&quot;挑一个顺眼的信&quot;。3B+ 的千兆 PHY 走 <strong>USB 2.0 总线</strong>（上限 ~480 Mbit/s），实测公认约 <strong>300 Mbit/s</strong>（无法跑满千兆）—— 这与&quot;快 3 倍 = 300&quot;吻合，也解释了英文维基为何把 &quot;full gigabit&quot; 留给 Pi 4/5。</p><p>→ <strong>通用教训</strong>：来源内部矛盾时，让<strong>硬件/物理约束</strong>当裁判；两个数字冲突时，&quot;能被机制解释的那个&quot;更可信。</p><hr><h2 id="四、用途判断-能跑什么-跑不动什么" tabindex="-1">四、用途判断：能跑什么 / 跑不动什么 <a class="header-anchor" href="#四、用途判断-能跑什么-跑不动什么" aria-label="Permalink to &quot;四、用途判断：能跑什么 / 跑不动什么&quot;">​</a></h2><h3 id="_4-1-❌-跑不动的-先说结论-省得浪费时间" tabindex="-1">4.1 ❌ 跑不动的（先说结论，省得浪费时间） <a class="header-anchor" href="#_4-1-❌-跑不动的-先说结论-省得浪费时间" aria-label="Permalink to &quot;4.1 ❌ 跑不动的（先说结论，省得浪费时间）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>想做的事</th><th>结论</th></tr></thead><tbody><tr><td><strong>本地大模型</strong>（llama.cpp / Ollama）</td><td><strong>跑不动</strong> —— 1 GB 内存 + Cortex-A53 四核，小参数量模型都极吃力。要本地 LLM 请上 <strong>Pi 5（8/16 GB）</strong> 或 x86 小主机</td></tr><tr><td><strong>Home Assistant 完整版</strong></td><td>⚠️ 能跑但<strong>吃力</strong>（官方推荐 Pi 4+；1 GB 内存紧张）</td></tr><tr><td>需要 &gt;2 GB 内存的容器编排 / 数据库</td><td>❌</td></tr></tbody></table><h3 id="_4-2-✅-跑得动的-7×24-常驻小节点最合适" tabindex="-1">4.2 ✅ 跑得动的（7×24 常驻小节点最合适） <a class="header-anchor" href="#_4-2-✅-跑得动的-7×24-常驻小节点最合适" aria-label="Permalink to &quot;4.2 ✅ 跑得动的（7×24 常驻小节点最合适）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用途</th><th>为什么合适</th></tr></thead><tbody><tr><td><strong>服务健康看门狗</strong></td><td>定时请求 + 异常推送，资源占用极小</td></tr><tr><td><strong>AdGuard Home / Pi-hole</strong>（内网 DNS 去广告）</td><td>3B+ 经典用途，全家设备生效</td></tr><tr><td><strong>Tailscale 出口 / 子网节点</strong></td><td>在外访问家庭内网</td></tr><tr><td><strong>异地备份节点</strong>（git 推到第二个 remote）</td><td>定时任务即可</td></tr><tr><td><strong>MQTT / 温湿度传感器网关</strong></td><td>GPIO + 传感器，原生强项</td></tr><tr><td><strong>网络启动 / USB 启动小服务器</strong></td><td>3B+ 原生支持两种启动方式（SD 卡非必须）</td></tr></tbody></table><h3 id="_4-3-🎯-对「ai-外脑」的具体价值-本库最相关" tabindex="-1">4.3 🎯 对「AI 外脑」的具体价值（本库最相关） <a class="header-anchor" href="#_4-3-🎯-对「ai-外脑」的具体价值-本库最相关" aria-label="Permalink to &quot;4.3 🎯 对「AI 外脑」的具体价值（本库最相关）&quot;">​</a></h3><p><strong>现状弱点（有据可查）</strong>：</p><ol><li><strong>全部 cron 跑在 Mac 上</strong> —— 做梦(07:00) / 科学日报(09:00) / 周刊监控(10:00) / GitHub 看门狗(每 15 分钟)；<strong>Mac 关机或休眠即停</strong>。</li><li><strong>代理是单点故障</strong> —— <code>http_proxy=127.0.0.1:8899</code> 一挂，<strong>LLM 调用与飞书投递同时失效</strong>，外部表现是&quot;任务全 FAILED 却没人知道&quot;。<strong>2026-09-23 起停摆 13 天</strong>即此因。</li></ol><p><strong>→ 3B+ 作为独立供电、独立网络路径的看门狗，正好补这个盲区。</strong></p><blockquote><p><strong>它的价值不是算力，是&quot;不在同一条故障链上&quot;。</strong> 一台不能跑 LLM 的机器，恰恰最适合用来监控那台跑 LLM 的机器。</p></blockquote><hr><h2 id="五、跨主题关联" tabindex="-1">五、跨主题关联 <a class="header-anchor" href="#五、跨主题关联" aria-label="Permalink to &quot;五、跨主题关联&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关联对象</th><th>关系</th></tr></thead><tbody><tr><td><code>topics/ai-brain/cron-outage-2026-09-23.md</code></td><td><strong>停摆事故</strong> —— 本条 4.3 的看门狗方案就是它的直接对策（事故 → 硬件级冗余）</td></tr><tr><td><code>topics/ai-brain/index.md</code></td><td>五个 cron job 清单；本条给出&quot;常驻侧&quot;的可能落点</td></tr><tr><td><code>topics/ai-system-architecture/</code></td><td>本地 LLM 主题 —— 本条给出<strong>硬件边界</strong>：&quot;1 GB / Cortex-A53 这条路线跑不动&quot;</td></tr><tr><td><code>topics/cybersecurity/</code></td><td>内网 DNS / 暴露面；对照 ADB 5555 那条元教训：<strong>便利换暴露</strong>（自托管越便利，暴露面越要数）</td></tr><tr><td><code>topics/ai-tools/android-tv-debloat-cleanyourtv.md</code></td><td>同属&quot;用低成本设备改造家庭基础设施&quot;</td></tr><tr><td><code>topics/ai-system-architecture/dsh-plugin-ecosystem.md</code></td><td>&quot;Token 自由&quot;一节的对照：<strong>别人补贴的算力 vs 自己买的算力</strong> —— 自托管是另一种&quot;不依赖别人窗口&quot;的选择</td></tr></tbody></table><hr><h2 id="六、待办-未决" tabindex="-1">六、待办 / 未决 <a class="header-anchor" href="#六、待办-未决" aria-label="Permalink to &quot;六、待办 / 未决&quot;">​</a></h2><ul><li>[ ] <strong>用途未定</strong> —— 用户仅分享照片，未指定项目（已问，待答）</li><li>[ ] 未核实：内存<strong>精确容量</strong>（1 GB 系反推，未读到 3B+ 直接参数行）、<strong>实测网口吞吐</strong>、SD 卡容量与系统镜像版本</li><li>[ ] 照片里那根 <strong>USB 3.0 AM-BM</strong> 线接了哪个外设（打印机？硬盘盒？）—— 待确认</li><li>[ ] 系统镜像：笔记本屏上出现 &quot;5.3.4&quot; 字样，未能对应到已知发行版版本号 → <strong>未核实，不猜</strong></li></ul>',33)])])}const c=r(e,[["render",a]]);export{b as __pageData,c as default};
